--- a/node/safe-merge/index.mjs
+++ b/node/safe-merge/index.mjs
@@ -1,3 +1,62 @@
+const DANGEROUS_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return false;
+  }
+  return Object.getPrototypeOf(value) === Object.prototype;
+}
+
+function deepClone(value) {
+  if (typeof value !== "object" || value === null) {
+    return value;
+  }
+
+  if (Array.isArray(value)) {
+    return value.map((item) => deepClone(item));
+  }
+
+  if (value instanceof Date) {
+    return new Date(value.getTime());
+  }
+
+  const prototype = Object.getPrototypeOf(value);
+  const clone = Object.create(prototype);
+  for (const key of Object.keys(value)) {
+    if (DANGEROUS_KEYS.has(key)) {
+      continue;
+    }
+    clone[key] = deepClone(value[key]);
+  }
+  return clone;
+}
+
+function mergeObjects(base, patch) {
+  const result = {};
+
+  for (const key of Object.keys(base)) {
+    if (DANGEROUS_KEYS.has(key)) {
+      continue;
+    }
+    result[key] = deepClone(base[key]);
+  }
+
+  for (const key of Object.keys(patch)) {
+    if (DANGEROUS_KEYS.has(key)) {
+      continue;
+    }
+    const baseValue = base[key];
+    const patchValue = patch[key];
+    if (isPlainObject(baseValue) && isPlainObject(patchValue)) {
+      result[key] = mergeObjects(baseValue, patchValue);
+    } else {
+      result[key] = deepClone(patchValue);
+    }
+  }
+
+  return result;
+}
+
 export function safeMerge(base, patch) {
-  return { ...base, ...patch };
+  return mergeObjects(base, patch);
 }
